"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8792],{76296:e=>{e.exports=JSON.parse('{"functions":[{"name":"_playerOwnsItemId","desc":"Returns whether the player holds any record of the given item. Currently\\nunused \u2014 the underscore prefix marks it as dead code kept for the\\ninline-logic paths.","params":[{"name":"player","desc":"claimed owner","lua_type":"Player"},{"name":"itemId","desc":"item to look for","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","private":true,"source":{"line":75,"path":"src/Server/Features/Shop/Handlers/Shop.luau"}},{"name":"giveItem","desc":"Builds an [ItemRecord] by hand and appends it to the profile via the\\n`inventory.++` path operator, then notifies the client with\\n`ITEM_SHOP_ITEM_ADD`.\\n\\nA duplicate of the identically named helper in [ShopService]; like that one\\nit bypasses [InventoryService], so it performs no stacking and always places\\nthe item in the bag. It additionally prints a debug line on every grant.","params":[{"name":"player","desc":"recipient","lua_type":"Player"},{"name":"itemId","desc":"item to grant","lua_type":"string"},{"name":"showInventory","desc":"whether the client should pop the inventory open","lua_type":"boolean?"},{"name":"quantity","desc":"amount, defaults to 1","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"Types.ItemRecord?"}],"function_type":"static","private":true,"source":{"line":110,"path":"src/Server/Features/Shop/Handlers/Shop.luau"}},{"name":"_isCodeRedeemed","desc":"Cache-then-DataStore check for whether this player already redeemed a code.\\n\\nUnused \u2014 `SHOP_REDEEM_CODE` forwards to [ShopService.redeemCode], which runs\\nits own copy of this logic against its own handle on the same\\n`redeemed_codes` DataStore.","params":[{"name":"player","desc":"redeemer","lua_type":"Player"},{"name":"code","desc":"code to check","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","private":true,"source":{"line":161,"path":"src/Server/Features/Shop/Handlers/Shop.luau"}}],"properties":[],"types":[],"name":"ShopHandler","desc":"Binds the client-facing `SHOP_*` actions for the shop subsystem.\\n\\nBindings: `SHOP_REDEEM_CODE`, `SHOP_GET_INVENTORY`, `SHOP_PURCHASE`,\\n`SHOP_REMOVE_ITEM`, `SHOP_EQUIP`, `SHOP_SELL_ITEM`, `SHOP_SELL_ALL` and\\n`SHOP_UNEQUIP`.\\n\\n:::caution Violates the thin-handler convention\\nEvery other handler in this codebase is a bind-shim: it validates its\\npayload and forwards to a service. This one is not. `SHOP_PURCHASE`\\ncarries full business logic inline \u2014 ownership checks, the coin debit and\\nitem granting \u2014 and that logic is **duplicated**, near-identically, in\\n[ShopService.purchaseItem]. The private `giveItem` and `_isCodeRedeemed`\\nhelpers here are likewise copies of their ShopService counterparts, along\\nwith a second handle on the `redeemed_codes` DataStore.\\n\\nThe two copies have already drifted: this handler gates `SHOP_PURCHASE` on\\n`item.canPurchaseMultiple` while [ShopService.purchaseItem] gates on\\n`ownershipLimit`, so the bound path and the service path enforce different\\nrules. New work belongs in [ShopService]; these inline copies should be\\ncollapsed into forwarding calls like `SHOP_REDEEM_CODE` and the sell\\nbindings already are.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":31,"path":"src/Server/Features/Shop/Handlers/Shop.luau"}}')}}]);